import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.concurrent.atomic.AtomicLong;
import java.util.concurrent.atomic.LongAdder;

public class Solution {

    public record BenchmarkResult(String strategy, long total, long elapsedNanos) {
        public double elapsedMillis() {
            return elapsedNanos / 1_000_000.0;
        }
    }

    public static long countWithSynchronized(int threads, int iterations) {
        validate(threads, iterations);
        SynchronizedCounter counter = new SynchronizedCounter();
        List<Thread> workers = new ArrayList<>(threads);
        for (int t = 0; t < threads; t++) {
            workers.add(Thread.ofPlatform().name("sync-" + t).start(() -> {
                for (int i = 0; i < iterations; i++) {
                    counter.increment();
                }
            }));
        }
        joinAll(workers);
        return counter.value();
    }

    public static long countWithAtomic(int threads, int iterations) {
        validate(threads, iterations);
        AtomicLong counter = new AtomicLong();
        List<Thread> workers = new ArrayList<>(threads);
        for (int t = 0; t < threads; t++) {
            workers.add(Thread.ofPlatform().name("atomic-" + t).start(() -> {
                for (int i = 0; i < iterations; i++) {
                    counter.incrementAndGet();
                }
            }));
        }
        joinAll(workers);
        return counter.get();
    }

    public static long countWithLongAdder(int threads, int iterations) {
        validate(threads, iterations);
        LongAdder counter = new LongAdder();
        List<Thread> workers = new ArrayList<>(threads);
        for (int t = 0; t < threads; t++) {
            workers.add(Thread.ofPlatform().name("adder-" + t).start(() -> {
                for (int i = 0; i < iterations; i++) {
                    counter.increment();
                }
            }));
        }
        joinAll(workers);
        return counter.sum();
    }

    public static long countWithStripedCells(int threads, int iterations) {
        validate(threads, iterations);
        // 16 longs por thread: 128 bytes, maior que uma linha de cache típica de 64 bytes.
        long[] cells = new long[threads * 16];
        List<Thread> workers = new ArrayList<>(threads);
        for (int t = 0; t < threads; t++) {
            int index = t * 16;
            workers.add(Thread.ofPlatform().name("striped-" + t).start(() -> {
                for (int i = 0; i < iterations; i++) {
                    cells[index]++;
                }
            }));
        }
        joinAll(workers);
        long total = 0;
        for (int t = 0; t < threads; t++) {
            total += cells[t * 16];
        }
        return total;
    }

    public static BenchmarkResult benchmark(String strategy, int threads, int iterations) {
        if (strategy == null) {
            throw new IllegalArgumentException("strategy não pode ser nula");
        }
        validate(threads, iterations);
        long start = System.nanoTime();
        long total = switch (strategy.toLowerCase(Locale.ROOT)) {
            case "synchronized" -> countWithSynchronized(threads, iterations);
            case "atomic" -> countWithAtomic(threads, iterations);
            case "adder" -> countWithLongAdder(threads, iterations);
            case "striped" -> countWithStripedCells(threads, iterations);
            default -> throw new IllegalArgumentException("estratégia desconhecida: " + strategy);
        };
        long elapsed = System.nanoTime() - start;
        return new BenchmarkResult(strategy, total, elapsed);
    }

    private static void validate(int threads, int iterations) {
        if (threads < 1 || threads > 1024) {
            throw new IllegalArgumentException("threads deve estar entre 1 e 1024");
        }
        if (iterations < 0 || iterations > 100_000_000) {
            throw new IllegalArgumentException("iterations deve estar entre 0 e 100_000_000");
        }
    }

    private static void joinAll(List<Thread> threads) {
        boolean interrupted = false;
        for (Thread thread : threads) {
            while (true) {
                try {
                    thread.join();
                    break;
                } catch (InterruptedException e) {
                    interrupted = true;
                }
            }
        }
        if (interrupted) {
            Thread.currentThread().interrupt();
        }
    }

    private static final class SynchronizedCounter {
        private long value;

        synchronized void increment() {
            value++;
        }

        synchronized long value() {
            return value;
        }
    }
}

