import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

class SolutionTest {

    @Test
    void todosOsContadoresConcordamComPoucasThreads() {
        assertEquals(4_000, Solution.countWithSynchronized(1, 4_000));
        assertEquals(4_000, Solution.countWithAtomic(4, 1_000));
        assertEquals(4_000, Solution.countWithLongAdder(8, 500));
        assertEquals(4_000, Solution.countWithStripedCells(4, 1_000));
    }

    @Test
    void contadorZeradoRetornaZero() {
        assertEquals(0, Solution.countWithSynchronized(4, 0));
        assertEquals(0, Solution.countWithAtomic(4, 0));
        assertEquals(0, Solution.countWithLongAdder(4, 0));
        assertEquals(0, Solution.countWithStripedCells(4, 0));
    }

    @Test
    void benchmarkRetornaTotalENaoNomeDaEstrategia() {
        Solution.BenchmarkResult result = Solution.benchmark("atomic", 4, 20_000);
        assertEquals("atomic", result.strategy());
        assertEquals(80_000, result.total());
        assertTrue(result.elapsedNanos() >= 0);
        assertTrue(result.elapsedMillis() >= 0.0);
    }

    @Test
    void benchmarkAceitaNomeEmOutroCaixa() {
        Solution.BenchmarkResult result = Solution.benchmark("STRIPED", 2, 10);
        assertEquals("STRIPED", result.strategy());
        assertEquals(20, result.total());
    }

    @Test
    void entradasInvalidasFalhamAntesDeCriarThreads() {
        assertThrows(IllegalArgumentException.class, () -> Solution.countWithAtomic(0, 10));
        assertThrows(IllegalArgumentException.class, () -> Solution.countWithAtomic(1025, 10));
        assertThrows(IllegalArgumentException.class, () -> Solution.countWithLongAdder(2, -1));
        assertThrows(IllegalArgumentException.class, () -> Solution.benchmark(null, 2, 10));
        assertThrows(IllegalArgumentException.class, () -> Solution.benchmark("magic", 2, 10));
    }

    @Test
    void chamadasRepetidasNaoDeixamThreadsVivas() {
        for (int round = 0; round < 5; round++) {
            assertEquals(30_000, Solution.countWithStripedCells(6, 5_000));
        }
        long alive = Thread.getAllStackTraces().keySet().stream()
                .filter(t -> t.getName().startsWith("striped-"))
                .filter(Thread::isAlive)
                .count();
        assertEquals(0, alive);
    }
}
